proposals.refactored:
/**
 * Helper to create a JsonReader for a given JSON string and position it at the start of an array.
 */
private JsonReader createReader(String json) throws IOException {
    JsonReader reader = new JsonReader(reader(json));
    reader.beginArray();
    return reader;
}

/* ------------------- Boolean literals ------------------- */
@ParameterizedTest(name = "Boolean literal \"{0}\" should be {1}")
@CsvSource({
    "'True', true",
    "'TruE', true",
    "'False', false",
    "'FALSE', false"
})
public void testMixedCaseLiterals_BooleanLiterals(String literal, boolean expected) throws IOException {
    JsonReader reader = createReader("[" + literal + "]");
    if (expected) {
        assertThat(reader.nextBoolean())
            .named("Literal \"" + literal + "\" expected to be true")
            .isTrue();
    } else {
        assertThat(reader.nextBoolean())
            .named("Literal \"" + literal + "\" expected to be false")
            .isFalse();
    }
    reader.endArray();
    assertThat(reader.peek())
        .named("After reading boolean literal, reader should be at END_DOCUMENT")
        .isEqualTo(JsonToken.END_DOCUMENT);
}

/* ------------------- Null literals ------------------- */
@ParameterizedTest(name = "Null literal \"{0}\" should be parsed as null")
@CsvSource({
    "'NULL'",
    "'nulL'"
})
public void testMixedCaseLiterals_NullLiterals(String literal) throws IOException {
    JsonReader reader = createReader("[" + literal + "]");
    // Verify that the token is parsed as a null without throwing.
    reader.nextNull();
    reader.endArray();
    assertThat(reader.peek())
        .named("After reading null literal, reader should be at END_DOCUMENT")
        .isEqualTo(JsonToken.END_DOCUMENT);
}

/* ------------------- End‑of‑document peek ------------------- */
@Test
public void testMixedCaseLiterals_EndOfDocumentPeek() throws IOException {
    JsonReader reader = createReader("[True,TruE,False,FALSE,NULL,nulL]");
    // Consume all values without individual assertions (their correctness is covered by the
    // parameterized tests above).
    reader.nextBoolean(); // True
    reader.nextBoolean(); // TruE
    reader.nextBoolean(); // False
    reader.nextBoolean(); // FALSE
    reader.nextNull();    // NULL
    reader.nextNull();    // nulL
    reader.endArray();
    assertThat(reader.peek())
        .named("Reader should be at END_DOCUMENT after consuming the entire array")
        .isEqualTo(JsonToken.END_DOCUMENT);
}

