/* Helper that writes a single numeric value as a JSON array and returns the JSON string */
private String writeJsonArray(Object number) throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.beginArray();
    if (number instanceof BigInteger) {
        jsonWriter.value((BigInteger) number);
    } else if (number instanceof BigDecimal) {
        jsonWriter.value((BigDecimal) number);
    } else {
        jsonWriter.value((Number) number);
    }
    jsonWriter.endArray();
    jsonWriter.close();
    return stringWriter.toString();
}

