/** Creates a {@link JsonReader} positioned at the start of the JSON object. */
private JsonReader createReader() throws IOException {
  JsonReader reader = new JsonReader(reader("{\"a\": \"android\", \"b\": \"banana\"}"));
  reader.beginObject();
  return reader;
}

/** Advances the reader past the first key/value pair (\"a\":\"android\"). */
private JsonReader advancePastFirstEntry(JsonReader reader) throws IOException {
  reader.nextName();   // "a"
  reader.nextString(); // "android"
  return reader;
}

/** Advances the reader to the second key name (\"b\"). */
private JsonReader advanceToSecondKey(JsonReader reader) throws IOException {
  advancePastFirstEntry(reader);
  return reader;
}

