    Attributes a = new Attributes();
    a.put("Tot", VALUE_TOT);
    a.put("Hello", VALUE_HELLO);
    a.put("data-name", VALUE_DATA_NAME);
    return a;
}

private void verifyAttributeIterationOrder(Attributes attrs) {
    int seen = 0;
    for (Attribute attribute : attrs) {
        seen++;
        assertEquals(
            "Attribute value at position " + seen + " should match expected sequential value",
            String.valueOf(seen),
            attribute.getValue()
        );
    }
}

private void verifyAttributeCount(Attributes attrs) {
    int count = 0;
    for (Attribute attribute : attrs) {
        count++;
    }
    assertEquals(
        "Total number of attributes should be " + EXPECTED_ATTRIBUTE_COUNT,
        EXPECTED_ATTRIBUTE_COUNT,
        count
    );
}

