// Helper method to copy a classpath resource into the temporary directory
private File copyResourceToTempDir(String resourcePath, File tempDir) throws IOException {
    File src = getFile(resourcePath);
    File dest = new File(tempDir, new File(resourcePath).getName());
    Files.copy(src.toPath(), dest.toPath());
    return dest;
}

