// ----------- Refactored Tests -----------

@Test
public void testHasTextWhenIterating_NonBlankTextNode() {
    Document doc = parseTestDocument();
    List<TextNode> textNodes = collectAllTextNodes(doc);
    for (TextNode textNode : textNodes) {
        assertFalse("Text node should not be blank", StringUtil.isBlank(textNode.text()));
    }
}

@Test
public void testHasTextWhenIterating_FirstTextNodeContent() {
    Document doc = parseTestDocument();
    TextNode first = findFirstTextNode(doc);
    assertEquals("First text node should be 'One '", "One ", first.text());
    assertEquals("First text node whole text should be 'One '", "One ", first.getWholeText());
}

@Test
public void testHasTextWhenIterating_FoundFirstFlag() {
    Document doc = parseTestDocument();
    boolean foundFirst = (findFirstTextNode(doc) != null);
    assertTrue("At least one TextNode must be found", foundFirst);
}

// ----------- Helper Methods -----------

private Document parseTestDocument() {
    return Jsoup.parse("<div>One <p>Two <p>Three");
}

private List<TextNode> collectAllTextNodes(Document doc) {
    List<TextNode> result = new ArrayList<>();
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                result.add((TextNode) node);
            }
        }
    }
    return result;
}

private TextNode findFirstTextNode(Document doc) {
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                TextNode textNode = (TextNode) node;
                if (!StringUtil.isBlank(textNode.text())) {
                    return textNode;
                }
            }
        }
    }
    return null; // No non‑blank TextNode found
}

